import type { StreamFn } from "@earendil-works/pi-agent-core";
import type { Model } from "@earendil-works/pi-ai";
import { streamSimple } from "@earendil-works/pi-ai/api/openai-completions";

/** Explicit API-key auth only; no local OAuth files, config discovery or hidden retries. */
export function compatibleModel(config: {
	baseUrl: string;
	model: string;
	apiKey: string;
	contextWindow?: number;
	fetch?: typeof globalThis.fetch;
}): { model: Model<"openai-completions">; streamFn: StreamFn } {
	const base = new URL(config.baseUrl);
	if (
		!["http:", "https:"].includes(base.protocol) ||
		base.username ||
		base.password ||
		base.search ||
		base.hash ||
		!config.model ||
		!config.apiKey
	)
		throw new Error("兼容接口配置无效");
	const model: Model<"openai-completions"> = {
		id: config.model,
		name: config.model,
		api: "openai-completions",
		provider: "blog-compatible",
		baseUrl: base.href.replace(/\/$/, ""),
		reasoning: false,
		input: ["text"],
		contextWindow: config.contextWindow ?? 128_000,
		maxTokens: 1600,
		cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
	};
	return {
		model,
		streamFn: (_selected, context, options) =>
			streamSimple(model, context, {
				...options,
				apiKey: config.apiKey,
				maxRetries: 0,
				timeoutMs: 45_000,
				maxTokens: 1600,
				fetch: config.fetch,
			}),
	};
}
