import { buildRagIndex, type RagIndex, retrieveChunks } from "./rag.ts";
import type { BlogPost, PostSummary } from "./types.ts";

export interface ReadPostOptions {
	level?: "outline" | "relevant" | "full";
	query?: string;
	chunkId?: string;
}

export class BlogCatalog {
	private readonly posts = new Map<string, BlogPost>();
	private readonly index: RagIndex;
	constructor(posts: readonly BlogPost[]) {
		for (const post of posts) {
			if (post.draft || post.password) continue;
			if (
				!post.id ||
				post.id.includes("..") ||
				/[\\\u0000]/.test(post.id) ||
				!post.url.startsWith("/posts/") ||
				/[\s\\?#]/.test(post.url)
			)
				throw new Error("博文标识或站内地址无效");
			const path = new URL(post.url, "https://blog.invalid").pathname;
			if (!path.startsWith("/posts/") || this.posts.has(post.id)) throw new Error("博文地址或重复 ID 无效");
			this.posts.set(post.id, structuredClone(post));
		}
		this.index = buildRagIndex([...this.posts.values()]);
	}
	disclose(id: string, options: ReadPostOptions = {}) {
		const post = this.read(id);
		const document = this.index.documents.find((item) => item.id === id)!;
		const summary = this.list().find((item) => item.id === id)!;
		const outline = document.chunks.map(({ id, heading, path }) => ({ id, heading, path }));
		if (options.level === "full")
			return { ...summary, revision: document.revision, outline, body: post.body, chunks: [] };
		let chunks = options.chunkId
			? document.chunks.filter((chunk) => chunk.id === options.chunkId)
			: options.level === "relevant"
				? retrieveChunks(options.query || "", document.chunks)
				: [];
		if (options.chunkId && !chunks.length) throw new Error("片段不在当前博文版本中");
		if (options.level === "relevant" && !chunks.length) chunks = document.chunks.slice(0, 1);
		return { ...summary, revision: document.revision, outline, chunks };
	}
	read(id: string): BlogPost {
		const post = this.posts.get(id);
		if (!post) throw new Error("只能读取公开目录中的博文 ID");
		return structuredClone(post);
	}
	list(): PostSummary[] {
		return [...this.posts.values()].map(({ id, title, url, description, tags, category }) => ({
			id,
			title,
			url,
			description,
			tags,
			category,
		}));
	}
	search(query: string): PostSummary[] {
		const stop = new Set([
			"如何",
			"怎么",
			"什么",
			"为什么",
			"请",
			"介绍",
			"一下",
			"的",
			"了",
			"是",
			"吗",
			"博客",
			"文章",
			"我",
			"想",
			"知道",
		]);
		const terms = [...new Intl.Segmenter("zh", { granularity: "word" }).segment(query.toLowerCase())]
			.filter((item) => item.isWordLike && !stop.has(item.segment))
			.map((item) => item.segment);
		if (!terms.length) return [];
		return [...this.posts.values()]
			.map((post) => {
				const metadata =
					`${post.title} ${post.description ?? ""} ${post.category ?? ""} ${(post.tags ?? []).join(" ")}`.toLowerCase();
				const body = post.body.toLowerCase();
				return {
					post,
					score: terms.reduce(
						(score, term) => score + (metadata.includes(term) ? 5 : 0) + (body.includes(term) ? 1 : 0),
						0,
					),
				};
			})
			.filter((item) => item.score > 0)
			.sort((a, b) => b.score - a.score || a.post.id.localeCompare(b.post.id))
			.slice(0, 8)
			.map(({ post: { body: _body, ...summary } }) => summary);
	}
	categories(): { name: string; count: number }[] {
		const counts = new Map<string, number>();
		for (const post of this.posts.values()) {
			const name = post.category || "未分类";
			counts.set(name, (counts.get(name) ?? 0) + 1);
		}
		return [...counts].map(([name, count]) => ({ name, count })).sort((a, b) => a.name.localeCompare(b.name));
	}
}
