import { createHash, randomUUID } from "node:crypto";
import type { BeginResult, BlogAnswer, BlogQuestion, RunStore, RunToken } from "./types.ts";

/** Inject a server-only PostgreSQL client returning rows (for example a Neon query wrapper). */
export type PostgresQuery = (sql: string, values: unknown[]) => Promise<Record<string, unknown>[]>;

export class PostgresRunStore implements RunStore {
	private readonly query: PostgresQuery;
	constructor(query: PostgresQuery) {
		this.query = query;
	}
	private async value(sql: string, values: unknown[]): Promise<unknown> {
		const rows = await this.query(sql, values);
		if (!rows.length) throw new Error("数据库未返回任务结果");
		return rows[0].value;
	}
	async begin(input: BlogQuestion, now: Date): Promise<BeginResult> {
		const fingerprint = createHash("sha256")
			.update(JSON.stringify([input.conversationId, input.question]))
			.digest("hex");
		const day = new Intl.DateTimeFormat("en-CA", {
			timeZone: "Asia/Shanghai",
			year: "numeric",
			month: "2-digit",
			day: "2-digit",
		}).format(now);
		return (await this.value("SELECT blog_begin($1,$2,$3,$4,$5,$6,$7,$8) AS value", [
			input.identity.id,
			input.requestId,
			input.conversationId,
			fingerprint,
			input.question,
			day,
			randomUUID(),
			now.getTime(),
		])) as BeginResult;
	}
	async modelStart(token: RunToken, limit: number): Promise<number> {
		return Number(
			await this.value("SELECT blog_budget($1,$2,$3,$4,$5) AS value", [
				token.userId,
				token.requestId,
				token.leaseId,
				"model",
				limit,
			]),
		);
	}
	async toolStart(token: RunToken, limit: number): Promise<number> {
		return Number(
			await this.value("SELECT blog_budget($1,$2,$3,$4,$5) AS value", [
				token.userId,
				token.requestId,
				token.leaseId,
				"tool",
				limit,
			]),
		);
	}
	async append(token: RunToken, type: string, data: string): Promise<void> {
		await this.value("SELECT blog_mutate($1,$2,$3,$4,$5,$6) AS value", [
			token.userId,
			token.requestId,
			token.leaseId,
			"event",
			type,
			data,
		]);
	}
	async complete(token: RunToken, result: BlogAnswer): Promise<void> {
		await this.value("SELECT blog_mutate($1,$2,$3,$4,$5,$6) AS value", [
			token.userId,
			token.requestId,
			token.leaseId,
			"complete",
			"",
			JSON.stringify(result),
		]);
	}
	async fail(token: RunToken): Promise<void> {
		await this.value("SELECT blog_mutate($1,$2,$3,$4,$5,$6) AS value", [
			token.userId,
			token.requestId,
			token.leaseId,
			"fail",
			"",
			"",
		]);
	}
	async history(userId: string, conversationId: string): Promise<{ question: string; answer: string }[]> {
		const rows = await this.query(
			"SELECT question,result FROM blog_runs WHERE user_id=$1 AND conversation_id=$2 AND status='completed' ORDER BY seq DESC LIMIT 3",
			[userId, conversationId],
		);
		return rows.reverse().map((row) => ({
			question: String(row.question).slice(0, 2000),
			answer: (row.result as BlogAnswer).answer.slice(0, 4000),
		}));
	}
}
